import { Group, Mesh, PlaneGeometry, Object3D } from 'three/webgpu';
import { texture, uv, mul, float, StandardNodeMaterial } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

/**
 * @typedef {import('three/webgpu').Object3D} Object3D
 * @typedef {any} NodeConfig
 * @typedef {any} NodeContext
 */

/**
 * Creates a pricing list‑row UI element.
 *
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {Object3D}
 */
export default function createNode(config, ctx) {
	// ---- root object -------------------------------------------------
	const root = new Group();
	const [px, py, pz] = config.position ?? [0, 0, 0];
	const [rx, ry, rz] = config.rotation ?? [0, 0, 0];
	const [sx, sy, sz] = config.scale ?? [1, 1, 1];
	root.position.set(px, py, pz);
	root.rotation.set(rx, ry, rz);
	root.scale.set(sx, sy, sz);

	// ---- geometry ----------------------------------------------------
	const geometry = new PlaneGeometry(1, 1, 64, 64);

	// ---- textures -----------------------------------------------------
	const colorTex = ctx.textureLoader(config.assets?.imageUrl);
	const depthTex = ctx.textureLoader(config.assets?.depthMapUrl);

	// ---- material (TSL) -----------------------------------------------
	const material = new StandardNodeMaterial();
	material.colorNode = texture(colorTex, uv());
	// displacement from depth map (scaled to a subtle depth)
	material.displacementNode = mul(texture(depthTex, uv()), float(0.12));

	// machined‑metal PBR defaults
	material.metalness = 0.55;
	material.roughness = 0.5;
	material.clearcoat = 0.25;

	// ---- mesh ---------------------------------------------------------
	const mesh = new Mesh(geometry, material);
	root.add(mesh);

	// ---- GSAP timelines ------------------------------------------------
	const timelines = [];

	const riseOffset = 0.15; // scene units
	const riseDuration = 0.2; // seconds
	const hoverTL = gsap.timeline({ paused: true });
	hoverTL.to(root.position, { y: `+=${riseOffset}`, duration: riseDuration, ease: 'power3.out' });
	hoverTL.to(root.position, { y: `-=${riseOffset}`, duration: riseDuration, ease: 'power3.out' }, '+=0');
	timelines.push(hoverTL);

	// ---- interaction handlers -----------------------------------------
	root.userData.handlers = {
		/**
		 * @param {boolean} entering true on hover‑enter, false on hover‑leave
		 */
		hover(entering) {
			if (entering) hoverTL.play(0);
			else hoverTL.reverse();
		},
		click() {
			if (typeof ctx.emit === 'function') ctx.emit('hub-pricing.select');
		}
	};

	// ---- cinematic primitives -----------------------------------------
	if (Array.isArray(config.cinematicPrimitives)) {
		for (const prim of config.cinematicPrimitives) {
			const fn = ctx.primitives?.[prim.name];
			if (typeof fn === 'function') fn(root, prim.params);
		}
	}

	// ---- data bindings (exposed for external system) -----------------
	root.userData.bindings = config.dataBindings?.slice() ?? [];

	// ---- cleanup ------------------------------------------------------
	root.userData.cleanup = () => {
		// dispose three.js resources
		geometry.dispose();
		material.dispose();

		// kill GSAP timelines
		for (const tl of timelines) tl.kill();

		// remove from scene graph
		if (root.parent) root.parent.remove(root);
	};

	return root;
}
